from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool
import itertools

n = 25
solver = Glucose4()
vpool = IDPool(start_from=n*n + 10)

def var(i, j):
    if i > j:
        i, j = j, i
    return i * n + j + 1

# Degree constraints
for i in range(n):
    edges = [var(i, j) for j in range(n) if i != j]
    # degree >= 3
    for clause in CardEnc.atleast(lits=edges, bound=3, encoding=EncType.seqcounter, vpool=vpool):
        solver.add_clause(clause)
    # degree <= 4
    for clause in CardEnc.atmost(lits=edges, bound=4, encoding=EncType.seqcounter, vpool=vpool):
        solver.add_clause(clause)

# No C3
for i, j, k in itertools.combinations(range(n), 3):
    solver.add_clause([-var(i, j), -var(j, k), -var(i, k)])

# No C4
for i, j in itertools.combinations(range(n), 2):
    for k1, k2 in itertools.combinations([k for k in range(n) if k != i and k != j], 2):
        solver.add_clause([-var(i, k1), -var(j, k1), -var(i, k2), -var(j, k2)])

# No C5
for comb in itertools.combinations(range(n), 5):
    v0 = comb[0]
    for p in itertools.permutations(comb[1:]):
        if p[0] < p[-1]:
            v1, v2, v3, v4 = p
            solver.add_clause([
                -var(v0, v1),
                -var(v1, v2),
                -var(v2, v3),
                -var(v3, v4),
                -var(v4, v0)
            ])

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if model[var(i, j) - 1] > 0:
                edges.append((i, j))
    print(edges)
else:
    print("UNSAT")

