edges = [(0, 13), (0, 17), (0, 18), (1, 6), (1, 19), (1, 22), (2, 6), (2, 14), (2, 18), (3, 8), (3, 9), (3, 17), (4, 10), (4, 14), (4, 23), (5, 9), (5, 11), (5, 15), (6, 9), (6, 16), (7, 16), (7, 17), (7, 24), (8, 21), (8, 22), (9, 23), (10, 11), (10, 16), (11, 12), (11, 18), (12, 19), (12, 20), (12, 21), (13, 15), (13, 21), (14, 15), (17, 19), (20, 23), (20, 24), (22, 24)]

adj = {i: [] for i in range(25)}
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

def get_girth(adj):
    girth = float('inf')
    for i in range(25):
        dist = {i: 0}
        parent = {i: -1}
        q = deque([i])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    girth = min(girth, dist[u] + dist[v] + 1)
    return girth

print("Girth:", get_girth(adj))
